// Wejście: wzorzec p i tekst t (bez spacji). Wyjście: liczba wystąpień i pozycje (od 1).
#include <bits/stdc++.h>
using namespace std;

vector<int> prefixFunction(const string& s) {
    int n = s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string p, t;
    cin >> p >> t;
    int m = p.size();
    vector<int> pi = prefixFunction(p);
    vector<int> pos;
    for (int i = 0, k = 0; i < (int)t.size(); i++) {
        while (k > 0 && t[i] != p[k]) k = pi[k - 1];   // niezgodność: krótszy prefikso-sufiks
        if (t[i] == p[k]) k++;
        if (k == m) {                                  // całe p pasuje, kończy się na pozycji i
            pos.push_back(i - m + 2);                  // początek, numeracja od 1
            k = pi[k - 1];                             // szukamy dalej (wystąpienia mogą nachodzić)
        }
    }
    cout << pos.size() << "\n";
    for (int x : pos) cout << x << " ";
    cout << "\n";
}

