// Wejście: słowo s, liczba zapytań q, potem q czwórek a b c d (od 1, włącznie).
// Dla każdego zapytania: TAK, jeśli s[a..b] == s[c..d], wpp. NIE.
#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
const ull MOD = (1ULL << 61) - 1;

ull mulmod(ull a, ull b) {
    __uint128_t c = (__uint128_t)a * b;
    ull x = (ull)(c & MOD) + (ull)(c >> 61);
    if (x >= MOD) x -= MOD;
    return x;
}

struct Hasher {
    vector<ull> h, pw;
    Hasher(const string& s, ull B) : h(s.size() + 1, 0), pw(s.size() + 1, 1) {
        for (size_t i = 0; i < s.size(); i++) {
            h[i + 1] = (mulmod(h[i], B) + (unsigned char)s[i]) % MOD;
            pw[i + 1] = mulmod(pw[i], B);
        }
    }
    ull get(int l, int r) const {          // s[l..r), 0-based
        return (h[r] + MOD - mulmod(h[l], pw[r - l])) % MOD;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());
    ull B = rng() % (MOD - 1000) + 500;     // losowa podstawa — odporna na testy anty-hash
    string s;
    int q;
    cin >> s >> q;
    Hasher H(s, B);
    while (q--) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        bool eq = (b - a == d - c) && H.get(a - 1, b) == H.get(c - 1, d);
        cout << (eq ? "TAK" : "NIE") << "\n";
    }
}

