// Rozkład Lyndona (Duval) i najmniejsza rotacja przez Duvala.
#include <bits/stdc++.h>
using namespace std;

vector<string> duval(const string& s) {
    int n = s.size(), i = 0;
    vector<string> f;
    while (i < n) {
        int j = i + 1, k = i;
        while (j < n && s[k] <= s[j]) {
            if (s[k] < s[j]) k = i; else k++;
            j++;
        }
        while (i <= k) { f.push_back(s.substr(i, j - k)); i += j - k; }
    }
    return f;
}

string minCyclic(string s) {
    int n = s.size();
    s += s;
    int i = 0, ans = 0;
    while (i < n) {
        ans = i;
        int j = i + 1, k = i;
        while (j < 2 * n && s[k] <= s[j]) {
            if (s[k] < s[j]) k = i; else k++;
            j++;
        }
        while (i <= k) i += j - k;
    }
    return s.substr(ans, n);
}

int main() {
    string s;
    cin >> s;
    for (auto& w : duval(s)) cout << w << " ";
    cout << "\n" << minCyclic(s) << "\n";
}

